import importlib, json, sys
from pathlib import Path
src = Path(sys.path[1]).resolve()
canonical = importlib.import_module("polisyos.data_forge.kernel.schemas")
alias = importlib.import_module("polisyos.data_forge.kernel.pipeline.schemas")
api = importlib.import_module("polisyos.foundry.plugins.api")
names = ("CompatibilityMode", "SchemaRegistry", "SchemaVersion")
assert all(getattr(canonical, name) is getattr(alias, name) for name in names)
assert api.SimulationConfig.__module__ == "polisyos.foundry.plugins.api"
missing = {}
for name in (
    "polisyos.foundry.domain.schema",
    "polisyos.data_forge.kernel.schemas.codegen",
):
    try:
        importlib.import_module(name)
    except ModuleNotFoundError as error:
        missing[name] = error.name
    else:
        raise AssertionError(f"retired module unexpectedly imported: {name}")
assert missing == {
    "polisyos.foundry.domain.schema": "polisyos.foundry.domain.schema",
    "polisyos.data_forge.kernel.schemas.codegen": "polisyos.data_forge.kernel.schemas.codegen",
}
print(json.dumps({
    "sys_path_prefix": sys.path[:4],
    "canonical_origin": canonical.__file__,
    "alias_origin": alias.__file__,
    "plugin_api_origin": api.__file__,
    "canonical_objects": {name: f"{getattr(canonical, name).__module__}.{name}" for name in names},
    "alias_identity": {name: getattr(canonical, name) is getattr(alias, name) for name in names},
    "retired_module_missing_names": missing,
}, sort_keys=True))
